import time
import threading
import bisect
from typing import Callable


class TokenBucketLimiter:
    def __init__(
        self,
        capacity: float,
        refill_rate: float,
        now_fn: Callable[[], float] = time.monotonic,
    ):
        self._capacity = capacity
        self._refill_rate = refill_rate
        self._now_fn = now_fn
        self._lock = threading.Lock()
        # key -> (tokens, last_refill_time)
        self._buckets: dict[str, tuple[float, float]] = {}

    def _refill(self, key: str, now: float) -> float:
        """Refill tokens for key up to `now`. Returns available tokens."""
        entry = self._buckets.get(key)
        if entry is None:
            self._buckets[key] = (self._capacity, now)
            return self._capacity
        tokens, last_time = entry
        if last_time < now:
            elapsed = now - last_time
            tokens = min(self._capacity, tokens + elapsed * self._refill_rate)
            self._buckets[key] = (tokens, now)
        return tokens

    def allow(self, key: str, cost: float = 1) -> bool:
        if cost <= 0:
            raise ValueError("cost must be positive")
        if cost > self._capacity:
            return False
        with self._lock:
            now = self._now_fn()
            available = self._refill(key, now)
            if available >= cost - 1e-12:
                self._buckets[key] = (available - cost, now)
                return True
            return False

    def retry_after(self, key: str, cost: float = 1) -> float:
        if cost <= 0:
            raise ValueError("cost must be positive")
        if cost > self._capacity:
            return float("inf")
        with self._lock:
            now = self._now_fn()
            available = self._refill(key, now)
            if available >= cost - 1e-12:
                return 0.0
            if self._refill_rate <= 0:
                return float("inf")
            return (cost - available) / self._refill_rate

    def remaining(self, key: str) -> float:
        with self._lock:
            now = self._now_fn()
            return self._refill(key, now)

    def reset(self, key: str | None = None) -> None:
        with self._lock:
            if key is None:
                self._buckets.clear()
            else:
                self._buckets.pop(key, None)


class SlidingWindowLimiter:
    def __init__(
        self,
        limit: int,
        window_seconds: float,
        now_fn: Callable[[], float] = time.monotonic,
    ):
        self._limit = limit
        self._window_seconds = window_seconds
        self._now_fn = now_fn
        self._lock = threading.Lock()
        # key -> sorted list of event timestamps
        self._logs: dict[str, list[float]] = {}

    def _prune(self, key: str, now: float) -> list[float]:
        """Remove expired timestamps (now - t >= window_seconds) and return active list."""
        timestamps = self._logs.get(key)
        if timestamps is None:
            timestamps = []
            self._logs[key] = timestamps
        # Active events satisfy now - t < window_seconds, i.e. t > now - window_seconds
        # Expired: t <= now - window_seconds
        cutoff = now - self._window_seconds
        idx = bisect.bisect_right(timestamps, cutoff)
        if idx > 0:
            del timestamps[:idx]
        return self._logs[key]

    def allow(self, key: str, cost: int = 1) -> bool:
        if cost <= 0:
            raise ValueError("cost must be positive")
        with self._lock:
            now = self._now_fn()
            active = self._prune(key, now)
            if cost > self._limit or len(active) + cost > self._limit:
                return False
            active.extend([now] * cost)
            return True

    def retry_after(self, key: str, cost: int = 1) -> float:
        if cost <= 0:
            raise ValueError("cost must be positive")
        if cost > self._limit:
            return float("inf")
        with self._lock:
            now = self._now_fn()
            active = self._prune(key, now)
            if len(active) + cost <= self._limit:
                return 0.0
            excess = len(active) + cost - self._limit
            # The excess oldest timestamps must expire.
            # active[excess - 1] is the last one among the excess to expire.
            target_time = active[excess - 1] + self._window_seconds
            return target_time - now

    def remaining(self, key: str) -> int:
        with self._lock:
            now = self._now_fn()
            active = self._prune(key, now)
            return self._limit - len(active)

    def reset(self, key: str | None = None) -> None:
        with self._lock:
            if key is None:
                self._logs.clear()
            else:
                self._logs.pop(key, None)
