from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP


def summarize_ledger(records, start_utc, end_utc, expected_currencies=None):
    # Normalize start_utc and end_utc to UTC (treat naive as UTC)
    if start_utc.tzinfo is None:
        start_utc = start_utc.replace(tzinfo=timezone.utc)
    else:
        start_utc = start_utc.astimezone(timezone.utc)

    if end_utc.tzinfo is None:
        end_utc = end_utc.replace(tzinfo=timezone.utc)
    else:
        end_utc = end_utc.astimezone(timezone.utc)

    def parse_ts_utc(ts_str):
        # Handle "Z" suffix for Python < 3.11 compatibility
        s = ts_str.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        dt = datetime.fromisoformat(s)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            dt = dt.astimezone(timezone.utc)
        return dt

    # Parse all record timestamps to UTC
    records_with_utc = []
    for i, rec in enumerate(records):
        tx_utc = parse_ts_utc(rec["timestamp"])
        records_with_utc.append((i, rec, tx_utc))

    # Deduplicate by idempotency_key, keeping earliest UTC timestamp
    # (ties broken by first occurrence in input order)
    by_key = {}
    for i, rec, tx_utc in records_with_utc:
        key = rec["idempotency_key"]
        if key not in by_key:
            by_key[key] = (i, rec, tx_utc)
        else:
            existing_i, existing_rec, existing_utc = by_key[key]
            if tx_utc < existing_utc or (tx_utc == existing_utc and i < existing_i):
                by_key[key] = (i, rec, tx_utc)

    deduped = list(by_key.values())

    # Half-open window filtering: start_utc <= tx_utc < end_utc
    filtered = []
    for i, rec, tx_utc in deduped:
        if start_utc <= tx_utc < end_utc:
            filtered.append((i, rec, tx_utc))

    # Build currency buckets
    buckets = {}

    # Initialize expected_currencies with zeros
    if expected_currencies:
        for cur in expected_currencies:
            buckets[cur] = {
                "gross_sales": Decimal("0.00"),
                "refunds_total": Decimal("0.00"),
                "net_revenue": Decimal("0.00"),
                "charge_count": 0,
                "refund_count": 0,
            }

    for i, rec, tx_utc in filtered:
        cur = rec["currency"]
        if cur not in buckets:
            buckets[cur] = {
                "gross_sales": Decimal("0.00"),
                "refunds_total": Decimal("0.00"),
                "net_revenue": Decimal("0.00"),
                "charge_count": 0,
                "refund_count": 0,
            }

        amt = Decimal(str(rec["amount"])).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

        if rec["type"] == "charge":
            buckets[cur]["gross_sales"] += amt
            buckets[cur]["net_revenue"] += amt
            buckets[cur]["charge_count"] += 1
        elif rec["type"] == "refund":
            buckets[cur]["refunds_total"] += amt
            buckets[cur]["net_revenue"] -= amt
            buckets[cur]["refund_count"] += 1

    # Build summary list
    summary = []
    for cur, data in buckets.items():
        summary.append({
            "currency": cur,
            "gross_sales": str(data["gross_sales"]),
            "refunds_total": str(data["refunds_total"]),
            "net_revenue": str(data["net_revenue"]),
            "charge_count": data["charge_count"],
            "refund_count": data["refund_count"],
        })

    # Sort by net_revenue descending, then currency alphabetically ascending
    summary.sort(key=lambda item: (-Decimal(item["net_revenue"]), item["currency"]))

    return {"total_processed": len(filtered), "currencies": summary}
