import math
import re


def parse_proxy_log(line: str) -> dict | None:
    """Parse a single custom reverse-proxy access log line into a dict,
    or return None for malformed / empty / comment lines."""

    line = line.strip()
    if not line or line.startswith('#'):
        return None

    pos = 0
    length = len(line)

    # ── helpers ──────────────────────────────────────────────────────────

    def skip_ws():
        nonlocal pos
        while pos < length and line[pos] in ' \t':
            pos += 1

    def read_token():
        """Read the next whitespace-delimited token; None if exhausted."""
        nonlocal pos
        skip_ws()
        if pos >= length:
            return None
        start = pos
        while pos < length and line[pos] not in ' \t':
            pos += 1
        return line[start:pos]

    def read_quoted():
        """Read a double-quoted string starting at pos (which must be '"').
        Handles \\" -> "  and  \\\\ -> \\.  Returns the unescaped content
        or None for an unclosed quote."""
        nonlocal pos
        pos += 1  # consume opening quote
        parts: list[str] = []
        while pos < length:
            c = line[pos]
            if c == '\\':
                if pos + 1 >= length:
                    return None          # dangling backslash
                nxt = line[pos + 1]
                if nxt == '"':
                    parts.append('"')
                    pos += 2
                elif nxt == '\\':
                    parts.append('\\')
                    pos += 2
                else:
                    # Any other \X: keep the backslash literally
                    parts.append('\\')
                    pos += 1
                continue
            if c == '"':
                pos += 1                # consume closing quote
                return ''.join(parts)
            parts.append(c)
            pos += 1
        return None                    # unclosed quote

    # ── timestamp ────────────────────────────────────────────────────────

    timestamp = read_token()
    if timestamp is None or 'T' not in timestamp:
        return None

    # ── client_ip ────────────────────────────────────────────────────────

    client_ip = read_token()
    if client_ip is None:
        return None
    if len(client_ip) >= 2 and client_ip[0] == '[' and client_ip[-1] == ']':
        client_ip = client_ip[1:-1]

    # ── method ───────────────────────────────────────────────────────────

    method = read_token()
    if method is None or not re.fullmatch(r'[A-Z]+', method):
        return None

    # ── path (must be double-quoted) ─────────────────────────────────────

    skip_ws()
    if pos >= length or line[pos] != '"':
        return None
    path = read_quoted()
    if path is None:
        return None

    # ── status ───────────────────────────────────────────────────────────

    status_str = read_token()
    if status_str is None:
        return None
    try:
        status = int(status_str)
    except ValueError:
        return None
    if status < 100 or status > 599:
        return None

    # ── bytes ────────────────────────────────────────────────────────────

    bytes_str = read_token()
    if bytes_str is None:
        return None
    if bytes_str == '-':
        bytes_val = None
    else:
        try:
            bytes_val = int(bytes_str)
        except ValueError:
            return None
        if bytes_val < 0:
            return None

    # ── upstream_ms ──────────────────────────────────────────────────────

    ms_str = read_token()
    if ms_str is None:
        return None
    if ms_str == '-':
        upstream_ms = None
    else:
        try:
            upstream_ms = float(ms_str)
        except ValueError:
            return None
        if math.isnan(upstream_ms) or math.isinf(upstream_ms) or upstream_ms < 0:
            return None

    # ── meta key=value pairs ─────────────────────────────────────────────

    meta: dict[str, str] = {}
    while True:
        skip_ws()
        if pos >= length:
            break

        # read key (stops at '=' or whitespace)
        start = pos
        while pos < length and line[pos] not in ' \t=':
            pos += 1
        key = line[start:pos]

        if not key:
            return None
        if pos >= length or line[pos] != '=':
            return None
        pos += 1  # consume '='

        if not re.fullmatch(r'[A-Za-z0-9_.-]+', key):
            return None

        # read value: either a quoted string or a bare token
        skip_ws()
        if pos >= length:
            return None

        if line[pos] == '"':
            value = read_quoted()
            if value is None:
                return None
        else:
            value = read_token()
            if value is None:
                return None

        meta[key] = value

    # ── result ───────────────────────────────────────────────────────────

    return {
        "timestamp": timestamp,
        "client_ip": client_ip,
        "method": method,
        "path": path,
        "status": status,
        "bytes": bytes_val,
        "upstream_ms": upstream_ms,
        "meta": meta,
    }
