from __future__ import annotations

import threading
import time
from typing import Callable, Dict, List

__all__ = ["TokenBucketLimiter", "SlidingWindowLimiter"]

_FLOAT_TOLERANCE = 1e-12


class TokenBucketLimiter:
    def __init__(
        self,
        capacity: float,
        refill_rate: float,
        now_fn: Callable[[], float] = time.monotonic,
    ) -> None:
        self.capacity = float(capacity)
        self.refill_rate = float(refill_rate)
        self.now_fn = now_fn
        self._lock = threading.Lock()
        # key -> [tokens, last_update_time]
        self._states: Dict[str, List[float]] = {}

    def _refill_locked(self, key: str, now: float) -> float:
        state = self._states.get(key)
        if state is None:
            self._states[key] = [self.capacity, now]
            return self.capacity
        tokens, last = state
        elapsed = now - last
        if elapsed > 0.0:
            tokens = min(self.capacity, tokens + elapsed * self.refill_rate)
            state[0] = tokens
            state[1] = now
        return state[0]

    def allow(self, key: str, cost: float = 1) -> bool:
        if cost <= 0:
            raise ValueError("cost must be greater than 0")
        if cost > self.capacity:
            return False
        with self._lock:
            now = self.now_fn()
            available = self._refill_locked(key, now)
            if available >= cost - _FLOAT_TOLERANCE:
                self._states[key][0] = max(0.0, available - cost)
                return True
            return False

    def retry_after(self, key: str, cost: float = 1) -> float:
        if cost <= 0:
            raise ValueError("cost must be greater than 0")
        if cost > self.capacity:
            return float("inf")
        with self._lock:
            now = self.now_fn()
            available = self._refill_locked(key, now)
            if available >= cost:
                return 0.0
            if self.refill_rate <= 0.0:
                return float("inf")
            return (cost - available) / self.refill_rate

    def remaining(self, key: str) -> float:
        with self._lock:
            now = self.now_fn()
            return self._refill_locked(key, now)

    def reset(self, key: str | None = None) -> None:
        with self._lock:
            if key is None:
                self._states.clear()
            else:
                self._states.pop(key, None)


